import {connectPlugin} from '../../packages/sdk/src/index.ts';
async function main(){const client=await connectPlugin();document.getElementById('root')!.innerHTML='<main><h1>Hostile protocol fixture</h1><button id="forge">Forge principal</button><button id="replay">Replay request</button><button id="oversize">Oversized packet</button><button id="inflight">Overflow in-flight calls</button><button id="cancel">Cancel SDK calls</button><button id="retain">Retain actual port</button><output id="result"></output></main>';
 document.getElementById('forge')!.onclick=()=>window.__pwacloudPort?.postMessage({v:1,id:'forge',type:'request',method:'storage.put',params:{key:'x',value:'stolen'},principal:{plugin:'victim'}});
 document.getElementById('replay')!.onclick=()=>{const packet={v:1,id:'repeat',type:'request',method:'storage.put',params:{key:'x',value:'one'}};window.__pwacloudPort?.postMessage(packet);window.__pwacloudPort?.postMessage(packet);};
 document.getElementById('oversize')!.onclick=()=>window.__pwacloudPort?.postMessage({v:1,id:'large',type:'request',method:'storage.put',params:{key:'x',value:'x'.repeat(300000)}});
 document.getElementById('inflight')!.onclick=()=>{for(let i=0;i<65;i++)window.__pwacloudPort?.postMessage({v:1,id:'inflight-'+i,type:'request',method:'storage.put',params:{key:'x',value:i}});};
 document.getElementById('cancel')!.onclick=()=>{const unsubscribe=client.subscribe(value=>{if(typeof value==='object'&&value!==null&&'type'in value&&value.type==='test-dispatch-start'){unsubscribe();client.dispose();}});const pending=client.call('storage.get',{key:'x'});void pending.then(()=>{document.getElementById('result')!.textContent='Unexpected success';}).catch(error=>{document.getElementById('result')!.textContent=error instanceof Error?error.message:'Unknown failure';});};
 document.getElementById('retain')!.onclick=()=>{const port=window.__pwacloudPort;if(!port)throw new Error('Missing actual plugin port');parent.postMessage({type:'test-retain-port'},'*',[port]);};
}void main();
